style.css:
@-moz-document domain("yanderesimulator.com") {
/* ? Background */
  body {
    background: linear-gradient(135deg, #fff0f5, #ffe6f0) !important; /* pastel gradient */
    color: #2b002b !important; /* dark plum text */
    font-family: "Georgia", serif !important;
  }

  /* ? Top Navigation Bar */
  nav {
    background-color: #2b002b !important; /* dark plum bar */
    border-bottom: 3px solid #ff99cc !important; /* pink accent line */
  }

  nav a {
    color: #ffe6f0 !important; /* soft pink links */
    font-family: "Courier New", monospace !important; /* hacker-y vibe */
    font-size: 15px !important;
    letter-spacing: 1px !important;
    padding: 10px 16px !important;
    text-transform: uppercase !important;
  }

  nav a:hover {
    color: #2b002b !important;  /* dark text on hover */
    background-color: #ff99cc !important; /* bright pink highlight */
    border-radius: 6px !important;
    transition: all 0.3s ease-in-out !important;
  }

  /* ? Buttons */
  button, .btn {
    background: #ff99cc !important;
    color: #2b002b !important;
    border: none !important;
    border-radius: 10px !important;
    padding: 8px 14px !important;
    font-weight: bold !important;
  }

  button:hover, .btn:hover {
    background: #2b002b !important;
    color: #ffe6f0 !important;
  }

  /* ? Links (general) */
  a {
    color: #cc0066 !important;
    text-decoration: none !important;
  }

  a:hover {
    color: #ff3399 !important;
    text-decoration: underline !important;
  }

  /* ? Headers */
  h1, h2, h3 {
    font-family: "Times New Roman", serif !important;
    color: #660033 !important;
    text-shadow: 2px 2px #ffccdd !important;
  }

  /* ? Custom scrollbar */
  ::-webkit-scrollbar {
    width: 10px;
  }
  ::-webkit-scrollbar-track {
    background: #ffe6f0;
  }
  ::-webkit-scrollbar-thumb {
    background: #cc0066;
    border-radius: 10px;
  }
  ::-webkit-scrollbar-thumb:hover {
    background: #99004d;
  }
}
